 ($ws$jl-sliced-error-analysis$ws$, $ws$ניתוח שגיאות לפי פרוסות$ws$, $ws$סדר יום: מתייגים תנאים (10 ד׳) · גיליון (15 ד׳) · הפרוסה הגרועה (10 ד׳) · תוכנית צילום (10 ד׳)$ws$, $ws$practice$ws$, $ws$evaluate$ws$, 45, array[$ws$לתייג כל תמונת בדיקה בתנאי (תאורה, מרחק, רקע, חפיפה).$ws$, $ws$לחשב שיעור שגיאה לכל פרוסה ולמצוא את הגרועה.$ws$, $ws$לתכנן צילום ממוקד במקום ״עוד תמונות״.$ws$]::text[], $ws$[{"title": "גיליון פרוסות", "instructions": "1. נפתח גיליון עם 50 תמונות בדיקה ועמודות: תאורה, מרחק, רקע, חפיפה, תוצאה.\n2. ממלאים את העמודות לכל תמונה לפי מה שרואים בה, ולא לפי זיכרון.\n3. מחשבים לכל ערך בעמודה את שיעור הטעויות.\n4. מסמנים בצבע את הפרוסה החמורה ביותר.", "kind": "group", "tool_hook": "cloud_train"}, {"title": "תוכנית צילום ממוקד", "instructions": "1. מגדירים 20 תמונות חדשות לפרוסה הגרועה: תנאים, מקום, זמן.\n2. מעריכים מה ישתפר: כמה תמונות נוספות יפחיתו כמה טעויות?\n3. מחלקים צלמים ומועד הגשה.", "kind": "group", "tool_hook": "series_capture"}]$ws$::jsonb, $ws$[{"label": "גיליון אלקטרוני עם 50 תמונות בדיקה", "kind": "supply"}, {"label": "תוצאות הסבב", "kind": "supply"}, {"label": "טבלת פרוסות", "kind": "supply"}]$ws$::jsonb, $ws$מקורות: [05 #47], [08 §5]. העיקרון זהה ל-Gender Shades אבל על תנאי החפץ. שיפור מודל הוא ניהול דאטה ממוקד ולא ״עוד תמונות״. יש לשמור על אנונימיות: אין אנשים בתמונות.

── סדר יום ──
